const http=require("http"),fs=require("fs"),url=require("url"),server=http.createServer((req,res)=>{const parsedUrl=url.parse(req.url,!0);let path=parsedUrl.pathname,fileName="";switch(path){case"/":case"/home":fileName="pages/home.html";break;case"/menu":fileName="pages/menu.html";break;case"/gallery":fileName="pages/gallery.html";break;case"/bookhall":fileName="pages/bookhall.html";break;case"/contact":fileName="pages/contact.html";break;default:fileName="pages/404.html"}fs.readFile(fileName,(err,data)=>{err?(res.writeHead(500,{"Content-Type":"text/html"}),res.write("<h1>500 Internal Server Error</h1>"),res.end()):("pages/404.html"===fileName?res.writeHead(404,{"Content-Type":"text/html"}):res.writeHead(200,{"Content-Type":"text/html"}),res.write(data),res.end())})});server.listen(3e3,()=>{console.log("Server running at http://localhost:3000")});